function validate([numBottles, numExchange]) {
  if (!Number.isInteger(numBottles) || numBottles < 1 || numBottles > 100) return 'numBottles must be between 1 and 100.';
  if (!Number.isInteger(numExchange) || numExchange < 2 || numExchange > 100) return 'numExchange must be between 2 and 100.';
  return null;
}

