function numWaterBottles(numBottles, numExchange) {
  let drunk = 0;
  let full = numBottles;
  let empty = 0;

  while (full > 0) {
    drunk += full;
    empty += full;
    full = Math.floor(empty / numExchange);
    empty = empty % numExchange;
  }

  return drunk;
}

