function numWaterBottles(numBottles, numExchange) {
  // One action at a time: drink a bottle if there is one, otherwise trade if possible.
  let full = numBottles, empties = 0, total = 0;
  for (;;) {
    if (full > 0) { full--; empties++; total++; }
    else if (empties >= numExchange) { empties -= numExchange; full++; }
    else break;
  }
  return total;
}

