function generate(rand, size) {
  if (size === 'large') {
    return [50 + Math.floor(rand() * 51), 2 + Math.floor(rand() * 99)];
  }
  const numBottles = 1 + Math.floor(rand() * (rand() < 0.7 ? 30 : 100));
  const numExchange = 2 + Math.floor(rand() * (rand() < 0.7 ? 9 : 99));
  return [numBottles, numExchange];
}
